      "name": "Missing Game Pass Quest Rewards",
      "description": "Players claim they have completed Game Pass quests or challenges but have not received the promised bonuses."
    },
    {
      "cluster": 3,
      "name": "Achievements Not Unlocking",
      "description": "Achievements or gamerscore entries remain locked despite meeting the required criteria."
    },
    {
      "cluster": 4,
      "name": "Minecraft Edition Availability Issues",
      "description": "Customers report missing, crashing, or reverted Minecraft titles and updates on Xbox One."
    },
    {
      "cluster": 5,
      "name": "Kinect Adapter Availability",
      "description": "Users need a Kinect adapter for newer Xbox models but cannot find or purchase the accessory."
    },
    {
      "cluster": 6,
      "name": "Custom Gamerpic Upload Problems",
      "description": "Players experience errors or silent rejections when trying to upload or change their custom gamer picture."
    },
    {
      "cluster": 7,
      "name": "Groove Music & Background Audio Controls",
      "description": "Questions about Groove Music retirement, transferring music, and adjusting background music volume in the new UI."
    },
    {
      "cluster": 8,
      "name": "Sports Game Content & Update Errors",
      "description": "Issues with NBA/WWE 2K titles not updating, missing DLC, or being blocked from playing after purchase."
    },
    {
      "cluster": 9,
      "name": "Party Chat Distortion & Disconnections",
      "description": "Users report distorted audio, scrolling glitches, and frequent disconnections in party chat after updates."
    },
    {
      "cluster": 10,
      "name": "Controller Connectivity & Drift Issues",
      "description": "Problems connecting controllers, firmware updates breaking functionality, and joystick drift on Xbox One controllers."
    },
